try {
  for (const [k, id] of Object.entries(IDS)) {
    const d = DATA[k]; if (!d || !d.plano) continue;
    db.prepare("INSERT OR IGNORE INTO tmkt_plano (id,empresa_id,nome,tema,status,ordem,criado_em) VALUES (?,?,?,?,'publicado',90,datetime('now'))").run(id, EMP, d.plano.nome, d.plano.tema);
    const cols = Object.keys(d.plano);
    db.prepare('UPDATE tmkt_plano SET ' + cols.map(c=>c+'=?').join(', ') + ' WHERE id=? AND empresa_id=?').run(...cols.map(c=>d.plano[c]), id, EMP);
    db.prepare('DELETE FROM tmkt_plano_cotas WHERE plano_id=?').run(id);
    const ic = db.prepare("INSERT OR IGNORE INTO tmkt_plano_cotas (id,empresa_id,plano_id,nome,preco,quantidade,cor,ordem,criado_em) VALUES (?,?,?,?,?,?,?,?,datetime('now'))");
    for (const c of d.cotas) ic.run(c.id, EMP, id, c.nome, c.preco, c.quantidade, c.cor, c.ordem);
    db.prepare("DELETE FROM tmkt_plano_fotos WHERE plano_id=? AND secao='galeria'").run(id);
    const iff = db.prepare("INSERT OR IGNORE INTO tmkt_plano_fotos (id,empresa_id,plano_id,foto,legenda,ordem,secao,criado_em) VALUES (?,?,?,?,?,?,?,datetime('now'))");
    for (const f of d.fotos) iff.run(f.id, EMP, id, f.foto, f.legenda, f.ordem, f.secao);
  }
  console.log('✅ migration 282: Esfriou, Sorte em Dobro (carro) e Arraiá aplicados');
} catch (e) { if (!/no such table/i.test(e.message)) throw e; console.log('↷ migration 282: tabelas ainda não existem — ok'); }
